import{_ as t,o as n,c as e,ag as i}from"./chunks/framework.Dx86EdC1.js";const h=JSON.parse('{"title":"Mutasi & Laporan Kependudukan","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-pengguna/mutasi-laporan.md","filePath":"panduan-pengguna/mutasi-laporan.md","lastUpdated":1791382762000}'),d={name:"panduan-pengguna/mutasi-laporan.md"};function r(o,a,s,u,l,p){return n(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="mutasi-laporan-kependudukan" tabindex="-1">Mutasi &amp; Laporan Kependudukan <a class="header-anchor" href="#mutasi-laporan-kependudukan" aria-label="Permalink to &quot;Mutasi &amp; Laporan Kependudukan&quot;">​</a></h1><h2 id="mutasi-penduduk" tabindex="-1">Mutasi Penduduk <a class="header-anchor" href="#mutasi-penduduk" aria-label="Permalink to &quot;Mutasi Penduduk&quot;">​</a></h2><p>Menu <strong>Kependudukan → Mutasi</strong> (<code>/admin/mutations</code>) mencatat perpindahan status penduduk.</p><h3 id="tipe-mutasi" tabindex="-1">Tipe Mutasi <a class="header-anchor" href="#tipe-mutasi" aria-label="Permalink to &quot;Tipe Mutasi&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tipe</th><th>Label</th><th>Data Tambahan</th></tr></thead><tbody><tr><td><code>birth</code></td><td>Kelahiran</td><td>Tanggal, keterangan</td></tr><tr><td><code>death</code></td><td>Kematian</td><td>Tanggal, alasan</td></tr><tr><td><code>moved_out</code></td><td>Pindah Keluar</td><td>Alamat tujuan (provinsi → desa), alasan, jumlah anggota pindah, nomor referensi</td></tr><tr><td><code>moved_in</code></td><td>Pindah Datang</td><td>Alamat asal, alasan, nomor referensi</td></tr></tbody></table><h3 id="langkah-input" tabindex="-1">Langkah Input <a class="header-anchor" href="#langkah-input" aria-label="Permalink to &quot;Langkah Input&quot;">​</a></h3><ol><li>Klik <strong>Tambah Mutasi</strong>.</li><li>Pilih penduduk yang bersangkutan.</li><li>Pilih tipe mutasi; form akan menampilkan isian khusus (mis. alamat tujuan untuk pindah keluar — lengkapi sampai tingkat desa via dropdown API Wilayah).</li><li>Isi tanggal kejadian, alasan, dan nomor referensi surat pindah (jika ada).</li><li><strong>Simpan</strong>.</li></ol><p>Setiap entri tercatat di audit trail (<code>created_by</code>).</p><h2 id="laporan-statistik" tabindex="-1">Laporan Statistik <a class="header-anchor" href="#laporan-statistik" aria-label="Permalink to &quot;Laporan Statistik&quot;">​</a></h2><p>Menu <strong>Kependudukan → Laporan</strong> (<code>/admin/reports/population</code>) menampilkan agregat:</p><ul><li>Jumlah KK &amp; penduduk (aktif).</li><li>Distribusi usia, jenis kelamin, pendidikan, pekerjaan.</li><li>Kelompok rentan &amp; penerima bansos (dari status ekonomi KK).</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Laporan ini adalah basis data yang dikirim ke SIK pada <a href="/panduan-pengembang/api-sik.html">Fase Integrasi API</a>. Data yang diolah bersifat <strong>agregat</strong>, bukan individu.</p></div><h2 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h2><p>Halaman <code>/admin/dashboard</code> merangkum statistik desa dan <strong>badge antrean</strong> (mis. jumlah surat menunggu verifikasi RT/staf/kades, permohonan PPID baru) agar aparatur tahu pekerjaan menumpuk.</p>',14)])])}const k=t(d,[["render",r]]);export{h as __pageData,k as default};
